"""Retention expiry date helpers (stdlib only)."""

import calendar
from datetime import date

__all__ = ["retention_end", "is_expired"]


def _clamp(year: int, month: int, day: int) -> date:
    last = calendar.monthrange(year, month)[1]
    return date(year, month, min(day, last))


def retention_end(created: date, months: int, policy: str) -> date:
    """Return the retention end date.

    policy:
      - "anniversary": same day-of-month `months` later, clamped to month end
        when the target day does not exist.
      - "month_end": last day of the month reached `months` after creation.
    """
    if months < 0:
        raise ValueError("months must be non-negative")
    total = created.year * 12 + (created.month - 1) + months
    year, month = divmod(total, 12)
    month += 1
    if policy == "anniversary":
        return _clamp(year, month, created.day)
    if policy == "month_end":
        return date(year, month, calendar.monthrange(year, month)[1])
    raise ValueError(f"unknown policy: {policy!r}")


def is_expired(created: date, months: int, policy: str, today: date) -> bool:
    """True once `today` is strictly AFTER the retention_end date."""
    return today > retention_end(created, months, policy)

